#!/bin/sh
# Generated by claude-rules-sync in claude-hub; don't edit here (change config/templates/cloud-context.sh).
# Cloud sessions only (claude.ai/code sets CLAUDE_CODE_REMOTE=true): print Taelor's rules, or the
# project's recall notes, as SessionStart context. On Taelor's computers it prints nothing, because the
# rules already load from ~/.claude/CLAUDE.md and hub-notes adds the recall notes.
# Each hook's output is capped at 10,000 characters, so the rules come in parts:
#   cloud-context.sh rules N   part N of docs/taelor-rules.md (whole paragraphs, under 9,000 chars)
#   cloud-context.sh recall    how to read and write notes, README "Where we left off", 2 newest notes
[ "$CLAUDE_CODE_REMOTE" = "true" ] || exit 0
cd "${CLAUDE_PROJECT_DIR:-.}" 2>/dev/null || exit 0

case "$1" in
rules)
  [ -f docs/taelor-rules.md ] || exit 0
  awk -v want="${2:-1}" -v cap=9000 '
    function flush() { if (sec != "") { if (len > 0 && len + length(sec) > cap) { part++; len = 0 }
                         if (part == want) printf "%s", sec; len += length(sec); sec = "" } }
    BEGIN { part = 1 }
    /^$/ { sec = sec "\n"; flush(); next }
    { sec = sec $0 "\n" }
    END { flush() }' docs/taelor-rules.md
  ;;
recall)
  cat <<'EOF'
# Recall notes (Taelor's projects)

Start: use the "Where we left off" section and the newest session notes below before reading anything
else; grep `docs/sessions/` only if they don't answer.
Finish (before your last commit): write `docs/sessions/<YYYY-MM-DD>-cloud-<HHMM>.md` with frontmatter
(project, computer: cloud, date, session, source: cloud, tags: [session-note, <project>]) and the sections
Decisions, Facts, Open items, Next (body under 1,500 characters), and update README "Where we left off"
(Updated <date>, State, Next, Open questions). Commit both with the work.

EOF
  if [ -f README.md ]; then
    awk '/^## Where we left off/ { on = 1 } on && /^## / && !/Where we left off/ { exit } on' README.md | head -c 2000
    echo
  fi
  for f in $(ls docs/sessions/*.md 2>/dev/null | sort | tail -n 2); do
    printf '\n--- %s ---\n' "$f"
    head -c 2500 "$f"
    echo
  done
  ;;
esac
exit 0
